-- STN_006 tenant SQL: reconciliation, returns, reusable templates.
ALTER TABLE stnew_transfers ADD COLUMN IF NOT EXISTS reconciliation_status VARCHAR(50) NULL AFTER status, ADD COLUMN IF NOT EXISTS reconciliation_resolution VARCHAR(191) NULL AFTER reconciliation_status, ADD COLUMN IF NOT EXISTS reconciliation_note TEXT NULL AFTER reconciliation_resolution, ADD COLUMN IF NOT EXISTS reconciled_at TIMESTAMP NULL AFTER reconciliation_note, ADD COLUMN IF NOT EXISTS reconciled_by BIGINT UNSIGNED NULL AFTER reconciled_at;
CREATE TABLE IF NOT EXISTS stnew_transfer_templates (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,name VARCHAR(191) NOT NULL,from_location_id BIGINT UNSIGNED NULL,from_store_id BIGINT UNSIGNED NULL,to_location_id BIGINT UNSIGNED NULL,to_store_id BIGINT UNSIGNED NULL,lines_json JSON NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_by BIGINT UNSIGNED NULL,updated_by BIGINT UNSIGNED NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,INDEX stnew_tpl_business_idx (business_id),INDEX stnew_tpl_from_idx (from_location_id, from_store_id),INDEX stnew_tpl_to_idx (to_location_id, to_store_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS stnew_transfer_returns (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,transfer_id BIGINT UNSIGNED NOT NULL,return_no VARCHAR(191) NOT NULL UNIQUE,return_qty_total DECIMAL(22,4) NOT NULL DEFAULT 0,reason TEXT NULL,status VARCHAR(50) NOT NULL DEFAULT 'created',created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,INDEX stnew_return_business_idx (business_id),INDEX stnew_return_transfer_idx (transfer_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO stnew_permissions (permission_key, permission_name, created_at, updated_at) SELECT 'stocktransfernew.reconcile','Stock Transfer New - Reconcile Variance',NOW(),NOW() WHERE NOT EXISTS (SELECT 1 FROM stnew_permissions WHERE permission_key='stocktransfernew.reconcile');
INSERT INTO stnew_permissions (permission_key, permission_name, created_at, updated_at) SELECT 'stocktransfernew.return','Stock Transfer New - Create Returns',NOW(),NOW() WHERE NOT EXISTS (SELECT 1 FROM stnew_permissions WHERE permission_key='stocktransfernew.return');
INSERT INTO stnew_permissions (permission_key, permission_name, created_at, updated_at) SELECT 'stocktransfernew.templates','Stock Transfer New - Manage Templates',NOW(),NOW() WHERE NOT EXISTS (SELECT 1 FROM stnew_permissions WHERE permission_key='stocktransfernew.templates');
